    "content": "import React from 'react'; import { Text, View, StyleSheet } from 'react-native'; const Index = () =\u003e { const names = ['Alice', 'Bob', 'Charlie', 'Guy']; return ( \u003cView style={styles.container}\u003e {names.map((name, index) =\u003e ( \u003cText key={index} style={styles.greeting}\u003e Hello, {name}! \u003c/Text\u003e ))} \u003c/View\u003e ); }; export default Index; // Styles const styles = StyleSheet.create({ container: { flex: 1, justifyContent: 'center', alignItems: 'center', padding: 20, backgroundColor: '#f5f5f5', }, greeting: { fontSize: 18, margin: 5, }, }); En JSX (la syntaxe utilisée par React et React Native), les accolades {} ont un rôle très précis : elles indiquent au compilateur qu’il faut sortir du monde HTML/JSX pour exécuter du code JavaScript classique.\nSans ces accolades, React traiterait votre code comme du simple texte brut.\nVoici exactement pourquoi elles sont indispensables dans votre exemple :\n1. Évaluer du code JavaScript dans le rendu Lorsque vous écrivez du JSX, vous décrivez une structure visuelle. Si vous écriviez directement names.map(...) au milieu de votre \u003cView\u003e, React afficherait littéralement le texte \"names.map(...)\" sur l’écran de votre téléphone.\nLes accolades forcent React à évaluer l’expression JavaScript :\nElles exécutent la fonction .map(). Elles génèrent le tableau de composants \u003cText\u003e. Elles injectent ensuite ce tableau de composants dans la \u003cView\u003e. 2. Le double rôle des accolades dans votre code Si vous regardez attentivement votre composant, vous utilisez les accolades à deux endroits différents pour cette même raison :\nAutour du .map() : Pour dire à React “Exécute cette fonction JavaScript pour boucler sur mon tableau”. Autour de {name} et {index} : À l’intérieur du composant \u003cText\u003e, les accolades permettent d’insérer la valeur de la variable JavaScript name au milieu du texte “Hello, !”, et la variable index dans la prop key. Un parallèle simple pour comprendre Imaginez que le JSX est une lettre que vous écrivez en français. Les accolades sont des zones “à remplir” dynamiquement :\n// En bon français : \u003cText\u003eHello, {name}!\u003c/Text\u003e // Ce que React comprend : // \"Écris 'Hello, ', va chercher la variable JavaScript 'name', puis écris '!'\" Props Les props permettent de passez en argument des valeurs à nos composants comme ceci :\nimport React from 'react'; import { Text, View, StyleSheet } from 'react-native'; // 1. Reusable Child Component const Greeting = (props) =\u003e { return ( \u003cView style={styles.greeting}\u003e \u003cText\u003eHello {props.name}!\u003c/Text\u003e \u003c/View\u003e ); }; // 2. Main Parent Component const LotsOfGreetings = () =\u003e { return ( \u003cView style={styles.container}\u003e \u003cGreeting name=\"Rexxar\" /\u003e \u003cGreeting name=\"Jaina\" /\u003e \u003cGreeting name=\"Valeera\" /\u003e \u003c/View\u003e ); }; // 3. Clean Export export default LotsOfGreetings; // 4. Proper Stylesheet (instead of inline styles) // Styles const styles = StyleSheet.create({ container: { flex: 1, justifyContent: 'center', alignItems: 'center', padding: 20, backgroundColor: '#f5f5f5', }, greeting: { fontSize: 18, margin: 5, }, }); Une méthode encore meilleure serait d’utiliser map :\nimport React from 'react'; import { Text, View, StyleSheet } from 'react-native'; // Define a component that takes an array of names as a prop const GreetingList = ({ names }) =\u003e { return ( \u003cView style={styles.container}\u003e {names.map((name, index) =\u003e ( \u003cText key={index} style={styles.greeting}\u003e Hello, {name}! \u003c/Text\u003e ))} \u003c/View\u003e ); }; // Parent component that uses GreetingList const Index = () =\u003e { // Array of names to pass as a prop const names = ['Alice', 'Bob', 'Charlie', 'Guy']; return ( \u003cGreetingList names={names} /\u003e ); }; export default Index; // Styles const styles = StyleSheet.create({ container: { flex: 1, justifyContent: 'center', alignItems: 'center', padding: 20, backgroundColor: '#f5f5f5', }, greeting: { fontSize: 18, margin: 5, }, }); Exercice Créez un composant pour afficher des cartes de chien dans l’exercice d’introduction à React Native. Utilisez la méthode map pour passer en paramètre les noms des images à afficher.\nVous rencontrerez un problème lié à l’importation dynamique des images. Pour résoudre ce problème, utilisez les ressources disponibles sur Internet pour trouver la solution appropriée.\nAfficher la Solution import React from 'react'; import { Text, View, StyleSheet, ScrollView, Image } from 'react-native'; const HScrollViewImageName = ({paths, names}) =\u003e { return ( \u003cScrollView horizontal contentContainerStyle={{flexDirection:'row'}} style={styles.scroll} \u003e {names.map((name, index) =\u003e ( \u003cView style={styles.container} key={index}\u003e \u003cImage style={styles.image} source={paths[index]} /\u003e \u003cText style={styles.text}\u003ename\u003c/Text\u003e \u003c/View\u003e ))} \u003c/ScrollView\u003e ); }; const Index = () =\u003e { // Array of names to pass as a prop const names = ['Golden', 'Corgie', 'Rottweiler']; const paths = [require('../assets/chiot1.jpg'), require('../assets/chiot2.jpg'), require('../assets/chiot3.jpg')]; return ( \u003cHScrollViewImageName names={names} paths={paths} /\u003e ); }; export default Index; const styles = StyleSheet.create({ container: { alignItems: 'center', justifyContent: 'center', padding:10, }, image: { height:400, width: 300, resizeMode: 'contain' }, scroll:{ flex:1, backgroundColor:'#fff', }, text: { fontSize: 18, textAlign: 'center', marginTop: 10, }, });",
    "description": "import React from 'react'; import { Text, View, StyleSheet } from 'react-native'; const Index = () =\u003e { const names = ['Alice', 'Bob', 'Charlie', 'Guy']; return ( \u003cView style={styles.container}\u003e {names.map((name, index) =\u003e ( \u003cText key={index} style={styles.greeting}\u003e Hello, {name}! \u003c/Text\u003e ))} \u003c/View\u003e ); }; export default Index; // Styles const styles = StyleSheet.create({ container: { flex: 1, justifyContent: 'center', alignItems: 'center', padding: 20, backgroundColor: '#f5f5f5', }, greeting: { fontSize: 18, margin: 5, }, }); En JSX (la syntaxe utilisée par React et React Native), les accolades {} ont un rôle très précis : elles indiquent au compilateur qu’il faut sortir du monde HTML/JSX pour exécuter du code JavaScript classique.",
