    "content": "Dans cette section, nous verrons comment dynamiser l’interface utilisateur grâce aux animations. En React Native, la gestion des animations repose sur une combinaison entre la gestion des états (state) pour contrôler les données à afficher, et la bibliothèque react-native-reanimated qui permet d’exécuter des transitions fluides et performantes directement sur le thread natif.\nFlatlist\nAnimation\nTableau dans un state en React En React, il ne faut jamais modifier directement un tableau existant dans l’état (comme faire data.push(nouvelleTache)), car React ne détectera pas le changement et ne rafraîchira pas l’écran.\nOn utilise l’opérateur de décomposition (…) pour créer une nouvelle copie du tableau avec l’élément ajouté :\n// ❌ À NE PAS FAIRE (Mutation directe) data.push(nouvelleTache); setData(data); // React ne détecte pas la modification ! // ✅ BONNE PRATIQUE (Immutabilité avec Spread) const nouveauTableau = [...data, nouvelleTache]; // Copie l'ancien tableau et ajoute le nouvel élément à la fin setData(nouveauTableau); // ✅ ENCORE MIEUX : Mise à jour fonctionnelle setData((prevData) =\u003e [...prevData, nouvelleTache]); Exercice Exercice À l’aide des valeurs de couleur ci-dessous :\nconst color1 = \"#000000\"; const color2 = \"#282A3A\"; const color3 = '#735F32'; const color4 = '#C69749'; Recréez l’affichage suivant :\n(Indice : J’utilise Dimensions.get('window').width pour déterminer la largeur des rectangles.)\nFaites en sorte que le bouton + ajoute une tâche. Indice : utiliser le spread operator ... et une mise à jour fonctionnelle d’état (Ex : setCount((prev) =\u003e prev + 1)). Faites en sorte qu’un swipe à droite sur une tâche entraîne sa suppression. Indice : Swipeable. Afficher la Solution Layout import { View, Text } from 'react-native' import React from 'react' import {Stack} from 'expo-router' import { GestureHandlerRootView } from 'react-native-gesture-handler' const RootLayout = () =\u003e { return ( \u003cGestureHandlerRootView\u003e \u003cStack\u003e \u003cStack.Screen name=\"index\" options={{headerShown: false}}/\u003e \u003c/Stack\u003e \u003c/GestureHandlerRootView\u003e ) } export default RootLayout Index import { StyleSheet, Text, View, TextInput, TouchableOpacity, Dimensions, FlatList, Keyboard} from 'react-native' import React, {useState} from 'react' import { SafeAreaView } from 'react-native-safe-area-context'; import { Swipeable } from 'react-native-gesture-handler' import Animated, {LinearTransition , Easing} from 'react-native-reanimated'; const color1 = \"#000000\"; const color2 = \"#282A3A\"; const color3 = '#735F32'; const color4 = '#C69749'; const index = () =\u003e { const [textInput,setTextInput] = useState('') const [data,setData] = useState([\"Pratiquer mon lancer de frisbee\", \"Me questionner sur la vie\", \"Corriger les examens\"]) const handlePressPlus = () =\u003e { setData((prev) =\u003e [...prev,textInput]) setTextInput('') Keyboard.dismiss() } const handleDelete = (index) =\u003e { setData((prev) =\u003e prev.filter((_,id) =\u003e id !== index)) } const RenderItem = ({index, item}) =\u003e { const afficheText = () =\u003e( \u003cView style={{width:150,height:10}}\u003e\u003c/View\u003e ); return( \u003cSwipeable renderLeftActions={afficheText} onSwipeableWillOpen={() =\u003e handleDelete(index)}\u003e \u003cView style={[styles.task, { width: Dimensions.get('window').width }]}\u003e \u003cText style={styles.taskText}\u003e{item}\u003c/Text\u003e \u003c/View\u003e \u003c/Swipeable\u003e ); } return ( \u003cSafeAreaView style={styles.container}\u003e \u003cView style={{flexDirection:\"row\"}}\u003e \u003cTextInput style={styles.textInput} onChangeText={setTextInput} placeholder='Entrez la tâche à accomplir' placeholderTextColor={color3} value={textInput} /\u003e \u003cTouchableOpacity onPress={handlePressPlus} style={styles.btnPlusContainer}\u003e \u003cText style={styles.btnPlus}\u003e+\u003c/Text\u003e \u003c/TouchableOpacity\u003e \u003c/View\u003e \u003cAnimated.FlatList style={styles.flatList} data={data} renderItem={({item,index}) =\u003e \u003cRenderItem index={index} item={item}/\u003e} keyExtractor={(item, index) =\u003e index.toString()} contentContainerStyle={{alignItems:'center'}} /\u003e \u003c/SafeAreaView\u003e ) } export default index const styles = StyleSheet.create({ container:{ backgroundColor:color1, flex:1, }, textInput:{ backgroundColor:color2, width:Dimensions.get('window').width - 56, height:56, paddingHorizontal:20, textAlign:'center', fontSize:16, color:color4, }, btnPlus:{ color:color1, fontSize:26 }, btnPlusContainer:{ backgroundColor:color4, height:56, width:56, justifyContent:\"center\", alignItems:\"center\" }, flatList:{ paddingVertical:30 }, task:{ paddingVertical:20, paddingHorizontal:10, marginVertical:5, backgroundColor:color2, width:Dimensions.get('window').width * 0.9, }, taskText:{ color:color4, }, minusBtn:{ color:color1, fontSize:26, }, btnMinusContainer:{ justifyContent:'center', alignItems:'center', backgroundColor:'red', width:56, height:56, marginVertical:5, } })",
